<?php
 namespace Pterodactyl\Http\Controllers\Admin\Dezerx; use Illuminate\View\View; use Illuminate\Http\Request; use Illuminate\Http\RedirectResponse; use Prologue\Alerts\AlertsMessageBag; use Pterodactyl\Models\Node; use Pterodactyl\Http\Controllers\Controller; use Pterodactyl\Services\Dezerx\Allocations\AllocationFolders; class AllocationFoldersController extends Controller { public function __construct(private AlertsMessageBag $alert) { } public function index(): View { $nodes = Node::query() ->select('id', 'name', 'location_id') ->with('location:id,short') ->withCount('allocations') ->orderBy('name') ->get(); return view('admin.dezerx.allocationfolders.index', [ 'enabled' => AllocationFolders::enabled(), 'nodes' => $nodes, 'counts' => $nodes ->mapWithKeys(fn (Node $node) => [ $node->id => count(AllocationFolders::node($node->id)['folders']), ]) ->all(), ]); } public function update(Request $request): RedirectResponse { $data = $request->validate(['enabled' => ['sometimes', 'boolean']]); AllocationFolders::setEnabled((bool) ($data['enabled'] ?? false)); $this->alert->success('Allocation folders have been updated.')->flash(); return redirect()->route('admin.dezerx.allocationfolders'); } public function store(Request $request, Node $node): RedirectResponse { $data = $request->validate([ 'name' => ['required', 'string', 'max:48'], 'icon' => ['nullable', 'string', 'max:32'], 'color' => ['nullable', 'string', 'max:16'], 'image' => ['nullable', 'string', 'max:300'], 'note' => ['nullable', 'string', 'max:240'], ]); AllocationFolders::add($node->id, $data['name'], $this->look($data)); $this->alert->success('Folder created.')->flash(); return $this->back($request, $node); } public function rename(Request $request, Node $node): RedirectResponse { $data = $request->validate([ 'folder' => ['required', 'string', 'max:64'], 'name' => ['present', 'nullable', 'string', 'max:48'], 'icon' => ['nullable', 'string', 'max:32'], 'color' => ['nullable', 'string', 'max:16'], 'image' => ['nullable', 'string', 'max:300'], 'note' => ['nullable', 'string', 'max:240'], ]); AllocationFolders::rename($node->id, $data['folder'], (string) ($data['name'] ?? '')); AllocationFolders::setMeta($node->id, $data['folder'], $this->look($data)); $this->alert->success('Folder saved.')->flash(); return $this->back($request, $node); } public function shift(Request $request, Node $node): RedirectResponse { $data = $request->validate([ 'folder' => ['required', 'string', 'max:64'], 'direction' => ['required', 'in:up,down'], ]); AllocationFolders::shift($node->id, $data['folder'], $data['direction'] === 'up' ? -1 : 1); return $this->back($request, $node); } public function move(Request $request, Node $node): RedirectResponse { $data = $request->validate([ 'folder' => ['required', 'string', 'max:64'], 'name' => ['required_if:folder,' . AllocationFolders::FRESH, 'nullable', 'string', 'max:48'], 'allocations' => ['required', 'array'], 'allocations.*' => ['integer'], ]); $fresh = $data['folder'] === AllocationFolders::FRESH; $folder = $fresh ? AllocationFolders::add($node->id, (string) $data['name']) : $data['folder']; $moved = AllocationFolders::move($node->id, $folder, $data['allocations']); $name = AllocationFolders::label($node->id, $folder); $this->alert->success(match (true) { $moved === 0 => 'Nothing moved. Those allocations are no longer on this node.', $data['folder'] === AllocationFolders::ALL => sprintf( '%s allocation%s taken out of their folder and back under their IP.', number_format($moved), $moved === 1 ? '' : 's', ), default => sprintf( '%s allocation%s moved into "%s"%s.', number_format($moved), $moved === 1 ? '' : 's', $name, $fresh ? ', which was made for them' : '', ), })->flash(); if ($fresh) { return redirect()->route('admin.nodes.view.allocation', [ 'node' => $node->id, 'folder' => $folder, ]); } return $this->back($request, $node); } public function destroy(Request $request, Node $node): RedirectResponse { $data = $request->validate([ 'folder' => ['required', 'string', 'max:64'], 'current' => ['nullable', 'string', 'max:64'], ]); if (str_starts_with($data['folder'], AllocationFolders::IP)) { AllocationFolders::reset($node->id, $data['folder']); $this->alert->success(sprintf( 'Reset. %s is listed under its own address again, and no allocation was touched.', substr($data['folder'], strlen(AllocationFolders::IP)), ))->flash(); return redirect()->route('admin.nodes.view.allocation', [ 'node' => $node->id, 'folder' => $data['folder'], ]); } $held = AllocationFolders::remove($node->id, $data['folder']); $this->alert->success($held === 0 ? 'Folder removed.' : sprintf( 'Folder removed. Its %s allocation%s %s back under their IP, and none of them were deleted.', number_format($held), $held === 1 ? '' : 's', $held === 1 ? 'is' : 'are', ))->flash(); $current = (string) ($data['current'] ?? AllocationFolders::ALL); return redirect()->route('admin.nodes.view.allocation', [ 'node' => $node->id, 'folder' => $current === '' || $current === $data['folder'] ? AllocationFolders::ALL : $current, ]); } private function look(array $data): array { $icon = (string) ($data['icon'] ?? ''); $color = (string) ($data['color'] ?? ''); return [ 'icon' => in_array($icon, AllocationFolders::icons(), true) ? $icon : '', 'color' => in_array($color, AllocationFolders::colors(), true) ? $color : '', 'image' => AllocationFolders::image((string) ($data['image'] ?? '')), 'note' => (string) ($data['note'] ?? ''), ]; } private function back(Request $request, Node $node): RedirectResponse { $folder = (string) $request->input('current', AllocationFolders::ALL); return redirect()->route('admin.nodes.view.allocation', [ 'node' => $node->id, 'folder' => $folder === '' ? AllocationFolders::ALL : $folder, ]); } } 